try:
    context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    context.load_cert_chain(certfile=cert_file, keyfile=key_file)
    secure_socket = context.wrap_socket(client_socket, server_side=True)

    file_path = secure_socket.recv(buffer_size).decode('utf-8').strip()
    if not file_path or not os.path.exists(file_path):
        return 'File not found'

    sha256_hash = hashlib.sha256()
    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(buffer_size)
            if not chunk:
                break
            sha256_hash.update(chunk)
    return sha256_hash.hexdigest()
except Exception as e:
    return str(e)

if not os.path.exists(file_path):
    raise ValueError("File does not exist")

try:
    with open(file_path, 'r') as f:
        data = json.load(f)
except json.JSONDecodeError:
    raise ValueError("Invalid JSON format")

# Validate required fields
for field in INPUT_JSON.get("required", []):
    if field not in data:
        raise ValueError(f"Required attribute '{field}' is missing")

# Validate types and email format
properties = INPUT_JSON.get("properties", {})
for field, rules in properties.items():
    if field in data:
        expected_type = rules.get("type")
        if expected_type is not None and not isinstance(data[field], expected_type):
            raise ValueError(f"Type mismatch for attribute '{field}'")

        if field == "email" and not re.match(EMAIL_REGEX, str(data[field])):
            raise ValueError("Invalid email format")

# Retrieve specified attribute
if attribute not in data:
    raise ValueError(f"Attribute '{attribute}' not found in the JSON object")

return data[attribute]

import os
file_hashes = {}
for root, _, files in os.walk(directory):
    for file in files:
        filepath = os.path.join(root, file)
        if re.search(pattern, filepath):
            sha256_hash = hashlib.sha256()
            try:
                with open(filepath, "rb") as f:
                    for byte_block in iter(lambda: f.read(4096), b""):
                        sha256_hash.update(byte_block)
                file_hashes[filepath] = sha256_hash.hexdigest()
            except (OSError, IOError):
                continue
return file_hashes

