+// parseGoWork reads the go.work file and extracts the directories listed in "use" directives.
+func parseGoWork(path string, fs afero.Fs) ([]string, error) {
+	var dirs []string
+	f, err := fs.Open(path)
+	if err != nil {
+		return nil, err
+	}
+	defer f.Close()
+
+	scanner := bufio.NewScanner(f)
+	for scanner.Scan() {
+		line := strings.TrimSpace(scanner.Text())
+		if strings.HasPrefix(line, "use ") {
+			dir := strings.TrimSpace(strings.TrimPrefix(line, "use "))
+			// go.work paths are relative to the go.work file
+			absDir := filepath.Join(filepath.Dir(path), dir)
+			dirs = append(dirs, absDir)
+		}
+	}
+	return dirs, scanner.Err()
+}
+
 // getDirList provides NewWatcher() with a list of directories to watch for changes.
 func (c *commandeer) getDirList() ([]string, error) {
 	var filenames []string
