 		}
 	}

+	// Also watch directories from go.work if it exists.
+	workspace := c.Cfg.GetString("module.workspace")
+	workingDir := c.Cfg.GetString("workingDir")
+	if workspace == "" {
+		workspace = filepath.Join(workingDir, "go.work")
+	} else if !filepath.IsAbs(workspace) {
+		workspace = filepath.Join(workingDir, workspace)
+	}
+
+	if workspace != "" {
+		if _, err := c.Fs.Source.Stat(workspace); err == nil {
+			workDirs, err := parseGoWork(workspace, c.Fs.Source)
+			if err == nil {
+				filenames = append(filenames, workDirs...)
+			} else {
+				c.logger.Errorln("failed to parse go.work:", err)
+			}
+		}
+	}
+
 	filenames = helpers.UniqueStringsSorted(filenames)

 	return filenames, nil
